import React,{useState}from'react';import{createRoot}from'react-dom/client';import HadiahPanel from '../../src/components/HadiahPanel.jsx';import GiftDetails from '../../src/components/templates/shared/GiftDetails.jsx';import{UIProvider}from'../../src/context/UIContext.jsx';import{api}from'../../src/api/client.js';import '../../src/styles/index.css';import '../../src/styles/atelier.css';
api.patch=async(_,body)=>({data:{giftSettings:body}});
function App(){const[inv,setInv]=useState({id:'gift-qa',giftSettings:{type:'both',bankAccounts:[{bankName:'Bank contoh',accountNumber:'0012345678',accountHolder:'Pemilik Contoh'}],shippingAddress:'Nama Penerima Contoh\nJl. Contoh No. 1, Kota Contoh'}}),[override,setOverride]=useState(null);return <UIProvider><main className="atelier-app" style={{display:'grid',gridTemplateColumns:'480px 390px',gap:48,padding:32,background:'#faf8ef',color:'#526745'}}><HadiahPanel invitation={inv} onUpdated={setInv} onLivePreview={setOverride}/><section><h2>Pratinjau hadiah — data uji</h2><GiftDetails gift={override?.giftSettings||inv.giftSettings}/></section></main></UIProvider>};createRoot(document.getElementById('root')).render(<App/>);
